"""`hsm sync`: regenerate a delimited block in ~/.ssh/config.

    # >>> hsm begin
    # Generated by `hsm sync`: changes inside this block will be overwritten.

    Host web01
        HostName 10.0.0.1
        User deploy
        Port 2222
        ProxyJump bastion
        IdentityFile "~/.ssh/id_ed25519"

    # Resets the scope to global for the lines after this block.
    Host *
    # <<< hsm end

Rules:
- we only write between the two markers; everything else stays byte for byte;
- if the markers aren't there, the block goes at the top: in ssh_config the
  first value found wins, so at the top hsm's values are not overridden by
  a `Host *` written further down;
- before every write there is a backup (0600) of the file as it was;
- idempotent: if the result is identical, nothing is written and no
  backup is created;
- malformed markers (only one, swapped, duplicated): we stop without
  touching anything, because we wouldn't know what is ours and what isn't.

The final `Host *` is needed because in ssh_config an option belongs to the
nearest `Host` block above it. With our block at the top, the global
options the user had at the start of the file would end up inside our last
host and stop applying to the others. `Host *` reopens a scope that applies
to everyone, like the start of the file.
"""

import difflib
import re
from collections.abc import Iterable
from dataclasses import dataclass
from datetime import UTC, datetime
from pathlib import Path

from hsm.errors import HsmError
from hsm.fsutil import atomic_write, ensure_private_dir, read_private
from hsm.inventory import Host

BEGIN = "# >>> hsm begin"
END = "# <<< hsm end"

_MAX_BACKUP_SUFFIX = 100

# Characters ssh_config interprets in an unquoted value:
# space and tab (separate arguments), '"' (quoting), '#' (comment),
# '\' (escape), '$' (${VAR} expansion), '=' (key=value separator).
_UNSAFE_UNQUOTED = frozenset(' \t"#\\$=')
# Inside quotes only these remain dangerous.
_UNSAFE_QUOTED = frozenset('"\\$')


class SshConfigError(HsmError):
    """~/.ssh/config is not in a state we can safely modify."""


@dataclass(frozen=True)
class SyncResult:
    """Outcome of `apply`: what was there, what is (or would be), where the backup is."""

    path: Path
    changed: bool
    old: str
    new: str
    backup: Path | None

    def diff(self) -> str:
        """Unified diff, useful for `--dry-run`."""
        return "".join(
            difflib.unified_diff(
                self.old.splitlines(keepends=True),
                self.new.splitlines(keepends=True),
                fromfile=str(self.path),
                tofile=f"{self.path} (after hsm sync)",
            )
        )


def render(hosts: Iterable[Host]) -> str:
    """The complete block, markers included. Same input, same output."""
    lines = [BEGIN, "# Generated by `hsm sync`: changes inside this block will be overwritten.", ""]
    for host in sorted(hosts, key=lambda h: h.alias):
        lines.append(f"Host {_value(host.alias)}")
        # In HostName ssh expands %h, %% etc.: "%" must be doubled, otherwise
        # an IPv6 zone like fe80::1%en0 makes every connection fail.
        lines.append(f"    HostName {_value(host.hostname.replace('%', '%%'))}")
        if host.user is not None:
            lines.append(f"    User {_value(host.user)}")
        # Port always explicit: it must not depend on a user's `Host *`.
        lines.append(f"    Port {host.port}")
        if host.jump_host is not None:
            lines.append(f"    ProxyJump {_value(host.jump_host)}")
        if host.identity_file is not None:
            # Quoted because the path may contain spaces; Host has already
            # excluded '"', '\\' and '%' from identity_file.
            lines.append(f'    IdentityFile "{_value(host.identity_file, quoted=True)}"')
            # Without it, ssh first tries all the agent's keys and the server
            # may disconnect for too many attempts before reaching this one.
            lines.append("    IdentitiesOnly yes")
        lines.append("")
    lines += ["# Resets the scope to global for the lines after this block.", "Host *", END]
    return "\n".join(lines) + "\n"


def apply(
    path: Path, block: str, *, dry_run: bool = False, now: datetime | None = None
) -> SyncResult:
    """Insert or replace the block in `path` (usually ~/.ssh/config)."""
    if not (block.startswith(BEGIN + "\n") and block.endswith(END + "\n")):
        raise ValueError("the block must start and end with the hsm markers")
    raw = _read_or_none(path)
    try:
        old = raw.decode("utf-8") if raw is not None else ""
    except UnicodeDecodeError:
        raise SshConfigError(f"{path} is not UTF-8 text: not modifying it.") from None

    new = _splice(path, old, block)
    if raw is not None and new == old:
        return SyncResult(path=path, changed=False, old=old, new=new, backup=None)
    if dry_run:
        return SyncResult(path=path, changed=True, old=old, new=new, backup=None)

    ensure_private_dir(path.parent)
    backup = _backup(path, raw, now or datetime.now(UTC)) if raw is not None else None
    # Last check before replacing: if an editor saved the file while we
    # were working, overwriting it would erase that change (and the backup
    # would only have the previous version). A window of a few microseconds
    # remains between this check and the rename: accepted.
    if _read_or_none(path) != raw:
        raise SshConfigError(
            f"{path} was modified during the sync: not overwriting it. Run hsm sync again."
        )
    atomic_write(path, new.encode("utf-8"))
    return SyncResult(path=path, changed=True, old=old, new=new, backup=backup)


def _read_or_none(path: Path) -> bytes | None:
    try:
        return read_private(path)
    except FileNotFoundError:
        return None


def _splice(path: Path, old: str, block: str) -> str:
    # Only "\n" separates lines, as in ssh. str.splitlines() would also split
    # on form feed, \x85, U+2028... and would see lines that ssh doesn't.
    lines = re.split(r"(?<=\n)", old)
    # strip(): a marker with surrounding whitespace (editor, CRLF) is still a
    # marker. Otherwise a second block would appear and the old one would stay active.
    begins = [i for i, line in enumerate(lines) if line.strip(" \t\r\n") == BEGIN]
    ends = [i for i, line in enumerate(lines) if line.strip(" \t\r\n") == END]
    if not begins and not ends:
        # Blank line separating it from the user's content. From the second
        # sync onwards it sits outside the markers, so it no longer changes.
        return block + ("\n" + old if old else "")
    if len(begins) == 1 and len(ends) == 1 and begins[0] < ends[0]:
        return "".join(lines[: begins[0]]) + block + "".join(lines[ends[0] + 1 :])
    raise SshConfigError(
        f"The hsm markers in {path} are not valid (exactly one "
        f"'{BEGIN}' followed by one '{END}' is required). Fix it by hand: nothing modified."
    )


def _backup(path: Path, content: bytes, now: datetime) -> Path:
    """0600 copy of the original file next to it, with a timestamp in the name."""
    stamp = now.astimezone(UTC).strftime("%Y%m%dT%H%M%S")
    for n in range(_MAX_BACKUP_SUFFIX):
        suffix = stamp if n == 0 else f"{stamp}-{n}"
        target = path.with_name(f"{path.name}.hsm-backup-{suffix}")
        try:
            # exclusive: an existing backup must never be overwritten.
            atomic_write(target, content, exclusive=True)
        except FileExistsError:
            continue
        return target
    raise SshConfigError(f"Too many backups of {path} in the same second.")


def _value(text: str, *, quoted: bool = False) -> str:
    """Second line of defense beyond Host validation.

    No value must be able to break the line, add directives or be read by
    ssh differently from how we wrote it: a single bad value would make the
    whole ~/.ssh/config invalid, for every host.
    """
    unsafe = _UNSAFE_QUOTED if quoted else _UNSAFE_UNQUOTED
    if not text.isprintable() or any(c in unsafe for c in text):
        raise SshConfigError(f"Value cannot be written to ssh_config: {text!r}")
    return text
